          "id": "hsr-item-140600",
          "name": "Trickery Coin",
          "kind": "item",
          "art": "../../Database/GameData/hsr/assets/items/140600.webp",
          "fields": {
            "rarity": "Rare",
            "type": "Mission"
          },
          "text": "From the \"Trickery's Traveler\": Cipher's bestowal, symbolizing her playful yet sincere blessings and desires."
